using System.Diagnostics;using System.IO.Compression;using System.Security.Cryptography;using System.Text.Json.Nodes;using Orbit.Core;
static class SkinChecks {
 public static int Run(string root,string probe){try{RunAsync(root,probe).GetAwaiter().GetResult();return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 static async Task RunAsync(string root,string probe){using var jar=ZipFile.OpenRead(Path.Combine(root,"versions","1.12.2","1.12.2.jar"));var entry=jar.GetEntry("assets/minecraft/textures/entity/steve.png")!;using var bytes=new MemoryStream();using(var input=entry.Open())input.CopyTo(bytes);byte[] png=bytes.ToArray();LocalSkins.Validate(png);bool rejected=false;try{LocalSkins.Validate(new byte[40]);}catch(InvalidDataException){rejected=true;}if(!rejected)throw new Exception("Bad PNG accepted");
 foreach(string version in new[]{"1.12.2","1.17","1.21.1","Fabric 26.1.2"})foreach(string model in new[]{"default","slim"}){string name="OrbitTester";string uuid=LaunchEngine.OfflineUuid(name);using var host=new SkinServer(new(name,uuid,model),png);host.Start();using var http=new HttpClient();
 foreach(string endpoint in new[]{"minecraftservices/privileges","minecraftservices/player/attributes","minecraftservices/privacy/blocklist","authserver/authenticate"}){
  using var denied=await http.GetAsync(host.Url+endpoint);
  if(denied.StatusCode!=System.Net.HttpStatusCode.Unauthorized)throw new Exception("Account endpoint must return 401: "+endpoint);
 }
 using(var denied=await http.PostAsync(host.Url+"sessionserver/session/minecraft/join",new StringContent("{}")))if(denied.StatusCode!=System.Net.HttpStatusCode.Forbidden)throw new Exception("Server join must remain rejected");
var profile=JsonNode.Parse(await http.GetStringAsync(host.Url+"sessionserver/session/minecraft/profile/"+uuid))!;string value=profile["properties"]![0]!["value"]!.ToString(),signature=profile["properties"]![0]!["signature"]!.ToString();var meta=JsonNode.Parse(await http.GetStringAsync(host.Url))!;using var rsa=RSA.Create();rsa.ImportFromPem(meta["signaturePublickey"]!.ToString());if(!rsa.VerifyData(System.Text.Encoding.UTF8.GetBytes(value),Convert.FromBase64String(signature),HashAlgorithmName.SHA1,RSASignaturePadding.Pkcs1))throw new Exception("Bad signature");
 var basePlan=LaunchEngine.Build(new LauncherSettings{GameRoot=root,Nickname=name},version);int cp=basePlan.Arguments.IndexOf("-cp");var plan=new LaunchPlan{Version=basePlan.Version,Java=basePlan.Java,GameDirectory=probe,Natives=Path.Combine(probe,"natives")};plan.Arguments.AddRange(new[]{"-javaagent:"+LocalSkins.Agent(probe)+"="+host.Url,"-Dauthlibinjector.noLogFile","-Dauthlibinjector.mojangNamespace=disabled","-Dauthlibinjector.mojangAntiFeatures=enabled","-cp",probe+Path.PathSeparator+basePlan.Arguments[cp+1],"OrbitSkinProbe",Guid.ParseExact(uuid,"N").ToString(),name,model,Convert.ToHexString(SHA256.HashData(png)).ToLowerInvariant()});using var process=LaunchEngine.Start(plan);var output=process.StandardOutput.ReadToEndAsync();var error=process.StandardError.ReadToEndAsync();await process.WaitForExitAsync();Console.WriteLine(version+" "+model+": "+await output);if(process.ExitCode!=0)throw new Exception(await error);Console.WriteLine("PASS Java "+basePlan.Version.JavaMajor+" skin integration (game not started)");}
 }
}
